INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_CO_JOBS', 'ACC_TYPE_CO', '0', 'JOB_STATE', 'L', 'Job State', NULL, '1', 'FROM T_CK_MST_JOB_STATE ORDER BY JBST_NAME', 'JBST_ID', 'JBST_NAME', 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_CO_JOBS', 'ACC_TYPE_CO', '1', 'RCD_DT_SUBMIT', 'R', 'Date Submitted', NULL, '2', '', NULL, NULL, 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_CO_JOBS', 'ACC_TYPE_CO', '0', 'Trucking Job by Job State', '100.0000', 'Y', '0', 'SELECT TRUCK.JOB_ID                                                AS JOB_ID,\n       JOB.JOB_SHIPMENT_TYPE                                       AS SHIPMENT_TYPE,\n       IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\')  AS JOB_DT_BOOKING,\n       IFNULL(DATE_FORMAT(TRUCK.JOB_DT_DELIVERY, \'%Y-%m-%d\'), \'-\') AS JOB_DT_DELIVERY,\n       COFF_ACCN.ACCN_NAME                                         AS CO_FF_ACCN       ,\n       TRUCK.JOB_TOTAL_CHARGE                                      AS CHARGES,\n       TO_ACCN.ACCN_NAME                                           AS TO_ACCN,\n       TRIP_LOC_FROM.TLOC_LOC_NAME                                 AS TLOC_LOC_NAME_FROM,\n       TRIP_LOC_TO.TLOC_LOC_NAME                                   AS TLOC_LOC_NAME_TO,\n       ( CASE\n           WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM   T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\n           WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\n           WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\n           ELSE TRUCK.JOB_DRV\n         END )                                                     AS DRV_NAME,\n       ( CASE\n           WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\n           WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\' \n           WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\n           ELSE TRUCK.JOB_VEH\n         END )                                                     AS VH_PLATE_NO,\n       ( CASE\n           WHEN TRUCK.JOB_SHIPMENT_REF = \'\' OR TRUCK.JOB_SHIPMENT_REF IS NULL THEN \'-\' \n		   ELSE TRUCK.JOB_SHIPMENT_REF\n         END )                                                     AS JOB_SHIPMENT_REF,\n       ( CASE\n           WHEN TRUCK.JOB_CUSTOMER_REF = \'\' OR TRUCK.JOB_CUSTOMER_REF IS NULL THEN \'-\'\n           ELSE TRUCK.JOB_CUSTOMER_REF\n         END )                                                     AS JOB_CUSTOMER_REF,\n       STATE.JBST_NAME                                             AS JOB_STATE,\n       IFNULL(DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\'), \'-\')  AS RCD_DT_SUBMIT\nFROM   T_CK_JOB_TRUCK TRUCK\n       LEFT JOIN T_CK_JOB JOB\n              ON TRUCK.JOB_PARENT = JOB.JOB_ID\n       LEFT JOIN T_CK_CT_TRIP TRIP\n              ON TRIP.TR_JOB = TRUCK.JOB_ID\n       LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\n              ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\n       LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\n              ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\n       LEFT JOIN T_CORE_ACCN COFF_ACCN\n              ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n       LEFT JOIN T_CORE_ACCN TO_ACCN\n              ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n       LEFT JOIN T_CK_MST_JOB_STATE STATE\n              ON JOB.JOB_STATE = STATE.JBST_ID\n       LEFT JOIN T_CK_RECORD_DATE RECORD\n              ON RECORD.RCD_ID = JOB.JOB_DATES\nWHERE  COFF_ACCN.ACCN_TYPE = \'ACC_TYPE_CO\'\n       AND JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\n       AND RECORD.RCD_DT_SUBMIT > \'@FIL_RCD_DT_SUBMIT_FROM@\'\n       AND RECORD.RCD_DT_SUBMIT < \'@FIL_RCD_DT_SUBMIT_TO@\' ');
