INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_SP_INVOICE', 'ACC_TYPE_SP', '0', 'PAYMENT_STATE', 'L', 'Payment State', NULL, '1', 'LIST', 'ALL,NEW,PAYING,PENDING,PAID,VERIFIED,APPROVED,CANCELLED', 'ALL,NEW,PAYING,PENDING,PAID,VERIFIED,APPROVED,CANCELLED', 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_SP_INVOICE', 'ACC_TYPE_SP', '1', 'INV_DT_ISSUE', 'R', 'Invoice Date', NULL, '2', '', NULL, NULL, 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_SP_INVOICE', 'ACC_TYPE_SP', '0', 'Invoice Details', '100.0000', 'Y', '0', 'SELECT COFF_ACCN.ACCN_NAME                                    AS CO_FF_ACCN,\n         TO_ACCN.ACCN_NAME                                      AS TO_ACCN,\n         TRUCK.JOB_ID                                           AS JOB_ID,\n         DN.DN_NO                                               AS DN_NO,\n         INV.INV_NO                                             AS INV_NO,\n         IFNULL(DATE_FORMAT(INV.INV_DT_ISSUE, \'%Y-%m-%d\'), \'-\') AS INV_DT_ISSUE,\n         TRUCK.JOB_TOTAL_CHARGE                                 AS JOB_CHARGE,\n         TRUCK.JOB_TOTAL_REIMBURSEMENTS                         AS JOB_TOTAL_REIMBURSEMENTS,\n         TRUCK.JOB_TOTAL_CHARGE \n         + TRUCK.JOB_TOTAL_REIMBURSEMENTS                       AS JOB_TOTAL_CHARGE,\n         INV.INV_AMT                                            AS INV_AMT,\n         INV.INV_VAT                                            AS INV_VAT,\n         INV.INV_TOTAL                                          AS INV_TOTAL,\n         TXN.PTX_PAYMENT_STATE                                  AS PTX_PAYMENT_STATE\n  FROM   T_CK_JOB_TRUCK TRUCK\n         LEFT JOIN T_CORE_ACCN COFF_ACCN\n                ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n         LEFT JOIN T_CORE_ACCN TO_ACCN\n                ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n         LEFT JOIN T_CK_CT_PLATFORM_INVOICE INV\n                ON INV.INV_JOB_ID = TRUCK.JOB_ID\n         LEFT JOIN T_CK_CT_DEBIT_NOTE DN\n                ON DN.DN_JOB_ID = TRUCK.JOB_ID\n         LEFT JOIN T_CK_PAYMENT_TXN TXN\n                ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', TRUCK.JOB_ID, \'%\')\n  WHERE  INV.INV_TO = TO_ACCN.ACCN_ID\n         AND DN.DN_FROM = TO_ACCN.ACCN_ID\n         AND DN.DN_TO = \'GLI\'\n         AND TXN.PTX_TYPE = \'BNKTF\'\n  	    AND TXN.PTX_PAYMENT_STATE = \'@FIL_PAYMENT_STATE_CAP@\'\n         AND INV.INV_DT_ISSUE > \'@FIL_INV_DT_ISSUE_FROM@\'\n         AND INV.INV_DT_ISSUE < \'@FIL_INV_DT_ISSUE_TO@\' ');
INSERT INTO `T_CORE_RPT_COLUMN` (`RPTCO_RPTID`, `RPTCO_ACCN_TYPE`, `RPTCO_TBL_IDX`, `RPTCO_IDX`, `RPTCO_DBCOL`, `RPTCO_CAPTION`, `RPTCO_COLTYPE`, `RPTCO_NUM_PRECISION`, `RPTCO_NUM_NO_ZERO`, `RPTCO_NUM_ACCFORMAT`, `RPTCO_NUM_NEG_ONLY`, `RPTCO_NUM_POS_ONLY`, `RPTCO_NUM_NOSIGN`, `RPTCO_IN_SUBTOTAL`, `RPTCO_IN_TOTAL`, `RPTCO_WIDTH`, `RPTCO_ROW_IDX`, `RPTCO_COL_IDX`, `RPTCO_SHOW`, `RPTCO_SORT_IDX`, `RPTCO_TAG`) VALUES ('RPT_SP_INVOICE', 'ACC_TYPE_SP', '0', '1', 'CO_FF_ACCN', 'Cargo Owner', 'T', '0', 'N', '0', 'N', 'N', 'N', 'N', 'N', '50', '1', '2', 'y', '-1', '');
