INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_SP_TO_UPAYMENT', 'ACC_TYPE_SP', '0', 'Upcoming Payments', '100.0000', 'Y', '0', 'SELECT IFNULL(DATE_FORMAT(TXN.PTX_DT_DUE, \'%Y-%m-%d\'), \'-\')   AS DUE_DATE,\n		   TO_ACCN.ACCN_NAME                                  AS TO_ACCN,\n           COUNT(DN.DN_JOB_ID)                                AS JOB_COUNT,\n           SUM(DN.DN_TOTAL)                                   AS AMOUNT_TOTAL           \n    FROM   T_CK_CT_DEBIT_NOTE DN\n           LEFT JOIN T_CORE_ACCN TO_ACCN\n                  ON TO_ACCN.ACCN_ID = DN.DN_FROM\n           LEFT JOIN T_CK_PAYMENT_TXN TXN\n                  ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', DN.DN_JOB_ID, \'%\')\n    WHERE  TO_ACCN.ACCN_TYPE = \'ACC_TYPE_TO\'\n            AND TXN.PTX_PAYMENT_STATE = \'NEW\'\n		    AND TXN.PTX_DT_DUE > \'@FIL_DUE_DATE_FROM@\'\n   		    AND TXN.PTX_DT_DUE < \'@FIL_DUE_DATE_TO@\'\n    GROUP  BY TO_ACCN,\n              DUE_DATE ');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_SP_TO_UPAYMENT', 'ACC_TYPE_TO', '0', 'Upcoming Payments', '100.0000', 'Y', '0', 'SELECT IFNULL(DATE_FORMAT(TXN.PTX_DT_DUE, \'%Y-%m-%d\'), \'-\')   AS DUE_DATE,\n		   TO_ACCN.ACCN_NAME                                  AS TO_ACCN,\n           COUNT(DN.DN_JOB_ID)                                AS JOB_COUNT,\n           SUM(DN.DN_TOTAL)                                   AS AMOUNT_TOTAL           \n    FROM   T_CK_CT_DEBIT_NOTE DN\n           LEFT JOIN T_CORE_ACCN TO_ACCN\n                  ON TO_ACCN.ACCN_ID = DN.DN_FROM\n           LEFT JOIN T_CK_PAYMENT_TXN TXN\n                  ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', DN.DN_JOB_ID, \'%\')\n    WHERE  TO_ACCN.ACCN_TYPE = \'ACC_TYPE_TO\'\n            AND TXN.PTX_PAYMENT_STATE = \'NEW\'\n		    AND TXN.PTX_DT_DUE > \'@FIL_DUE_DATE_FROM@\'\n   		    AND TXN.PTX_DT_DUE < \'@FIL_DUE_DATE_TO@\'\n    GROUP  BY TO_ACCN,\n              DUE_DATE ');
