INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_SP_HPAYMENT', 'ACC_TYPE_SP', '0', 'PAID_DATE', 'R', 'Payment Date', NULL, '1', '', NULL, NULL, 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_TO_HPAYMENT', 'ACC_TYPE_TO', '0', 'PAID_DATE', 'R', 'Payment Date', NULL, '1', '', NULL, NULL, 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_CO_HPAYMENT', 'ACC_TYPE_CO', '0', 'CO Historical Payment', '100.0000', 'Y', '0', 'SELECT IFNULL(DATE_FORMAT(TXN.PTX_DT_PAID, \'%Y-%m-%d\'), \'-\')    AS PAID_DATE,\n          CO_ACCN.ACCN_NAME                                     AS CO_ACCN,\n          TXN.PTX_PAYMENT_STATE                                 AS PYMNT_STATE,\n          COUNT(INV.INV_JOB_ID)                                 AS JOB_COUNT,\n          SUM(INV.INV_TOTAL)                                    AS AMOUNT_TOTAL\n   FROM   T_CK_CT_PLATFORM_INVOICE INV\n          LEFT JOIN T_CORE_ACCN CO_ACCN\n                 ON CO_ACCN.ACCN_ID = INV.INV_TO\n          LEFT JOIN T_CK_PAYMENT_TXN TXN\n                 ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', INV.INV_JOB_ID, \'%\')\n   WHERE  CO_ACCN.ACCN_TYPE = \'ACC_TYPE_CO\'\n          AND TXN.PTX_PAYMENT_STATE = \'PAID\'\n  		AND TXN.PTX_DT_PAID > \'@FIL_PAID_DATE_FROM@\'\n  		AND TXN.PTX_DT_PAID < \'@FIL_PAID_DATE_TO@\'\n   GROUP  BY CO_ACCN,\n            PAID_DATE ');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_SP_HPAYMENT', 'ACC_TYPE_SP', '0', 'Historical Payment', '100.0000', 'Y', '0', 'SELECT IFNULL(DATE_FORMAT(TXN.PTX_DT_PAID, \'%Y-%m-%d\'), \'-\')    AS PAID_DATE,\n          TO_ACCN.ACCN_NAME                                     AS TO_ACCN,\n          TXN.PTX_PAYMENT_STATE                                 AS PYMNT_STATE,\n          COUNT(INV.INV_JOB_ID)                                 AS JOB_COUNT,\n          SUM(INV.INV_TOTAL)                                    AS AMOUNT_TOTAL\n   FROM   T_CK_CT_PLATFORM_INVOICE INV\n          LEFT JOIN T_CORE_ACCN TO_ACCN\n                 ON TO_ACCN.ACCN_ID = INV.INV_TO\n          LEFT JOIN T_CK_PAYMENT_TXN TXN\n                 ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', INV.INV_JOB_ID, \'%\')\n   WHERE  TO_ACCN.ACCN_TYPE = \'ACC_TYPE_TO\'\n          AND TXN.PTX_PAYMENT_STATE = \'PAID\'\n  		  AND TXN.PTX_DT_PAID > \'@FIL_PAID_DATE_FROM@\'\n  		  AND TXN.PTX_DT_PAID < \'@FIL_PAID_DATE_TO@\'\n   GROUP  BY TO_ACCN,\n             PAID_DATE ');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_TO_HPAYMENT', 'ACC_TYPE_TO', '0', 'TO Historical Payment', '100.0000', 'Y', '0', 'SELECT IFNULL(DATE_FORMAT(TXN.PTX_DT_PAID, \'%Y-%m-%d\'), \'-\')    AS PAID_DATE,\n          TO_ACCN.ACCN_NAME                                     AS TO_ACCN,\n          TXN.PTX_PAYMENT_STATE                                 AS PYMNT_STATE,\n          COUNT(INV.INV_JOB_ID)                                 AS JOB_COUNT,\n          SUM(INV.INV_TOTAL)                                    AS AMOUNT_TOTAL\n   FROM   T_CK_CT_PLATFORM_INVOICE INV\n          LEFT JOIN T_CORE_ACCN TO_ACCN\n                 ON TO_ACCN.ACCN_ID = INV.INV_TO\n          LEFT JOIN T_CK_PAYMENT_TXN TXN\n                 ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', INV.INV_JOB_ID, \'%\')\n   WHERE  TO_ACCN.ACCN_TYPE = \'ACC_TYPE_TO\'\n          AND TXN.PTX_PAYMENT_STATE = \'PAID\'\n  		  AND TXN.PTX_DT_PAID > \'@FIL_PAID_DATE_FROM@\'\n  		  AND TXN.PTX_DT_PAID < \'@FIL_PAID_DATE_TO@\'\n   GROUP  BY TO_ACCN,\n             PAID_DATE ');
