INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_SP_COLLECTION', 'ACC_TYPE_SP', '0', 'PROCESS_DATE', 'R', 'Payment Date', NULL, '1', '', NULL, NULL, 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_SP_COLLECTION', 'ACC_TYPE_SP', '0', 'Collection Report', '100.0000', 'Y', '0', 'SELECT \n	IFNULL(DATE_FORMAT(JOURNAL.CJN_DT_CREATE, \'%Y-%m-%d\'), \'-\') AS PROC_DATE,\n    ACCN.ACCN_NAME AS ACCN, \n    ABS(SUM(CJN_UTILIZED)) AS AMOUNT\n  FROM \n    T_CK_CREDIT_JOURNAL JOURNAL \n    INNER JOIN T_CORE_ACCN ACCN ON ACCN.ACCN_ID = JOURNAL.CJN_COMPANY\n  WHERE JOURNAL.CJN_DT_CREATE > \'@FIL_PROCESS_DATE_FROM@\' \n    AND JOURNAL.CJN_DT_CREATE < \'@FIL_PROCESS_DATE_TO@\' \n  GROUP BY \n    ACCN.ACCN_NAME, \n    PROC_DATE\n  HAVING \n    SUM(JOURNAL.CJN_UTILIZED) < 0 ');
