INSERT INTO `T_CORE_RPT_FILTER` (`RPTF_ID`, `RPTF_ACCN_TYPE`, `RPTF_IDX`, `RPTF_NAME`, `RPTF_FILTYPE`, `RPTF_CAPTION`, `RPTF_BASIC`, `RPTF_BASIC_ROW`, `RPTF_LISTBOX_TBL`, `RPTF_LISTBOX_IDCOL`, `RPTF_LISTBOX_CAPCOL`, `RPTF_SHOW`, `RPTF_DEFVAL`, `RPTF_IFNULLVAL`, `RPTF_MANDATORY`) VALUES ('RPT_SP_MONITORING', 'ACC_TYPE_SP', '1', 'DN_DT_DUE', 'R', 'Receivable Invoice Due Date', NULL, '1', '', NULL, NULL, 'Y', NULL, NULL, 'N');
INSERT INTO `T_CORE_RPT_TABLE` (`RPTT_RPTID`, `RPTT_ACCN_TYPE`, `RPTT_TBL_IDX`, `RPTT_NAME`, `RPTT_WIDTH_PERC`, `RPTT_SHOW`, `RPTT_COLS`, `RPTT_RPT_QRY`) VALUES ('RPT_SP_MONITORING', 'ACC_TYPE_SP', '0', 'AP AR Monitoring', '100.0000', 'Y', '0', 'SELECT COFF_ACCN.ACCN_NAME                                      AS CO_FF_ACCN,\n        TO_ACCN.ACCN_NAME                                        AS TO_ACCN,\n        TXN.PTX_ID                                               AS PTX_ID,\n        TRUCK.JOB_ID                                             AS JOB_ID,\n        DN_TO.DN_NO                                              AS CO_DN_NO,\n        INV_CO.INV_NO                                            AS CO_INV_NO,\n        INV_TO.INV_NO                                            AS TO_INV_NO,\n        IFNULL(DATE_FORMAT(DN_TO.DN_DT_ISSUE, \'%Y-%m-%d\'), \'-\')	AS DN_DT_ISSUE,\n        IFNULL(DATE_FORMAT(DN_TO.DN_DT_DUE, \'%Y-%m-%d\'), \'-\')    AS DN_DT_DUE,\n        DN_TO.DN_AMT                                             AS OUTLAYCHARGE,\n        INV_TO.INV_TOTAL                                         AS INV_TOTAL,\n        DN_TO.DN_AMT - INV_TO.INV_TOTAL                          AS PAYMENT_TO_TV,\n        CASE\n          WHEN TXN.PTX_PAYMENT_STATE = \'APP_BILL\'\n               AND TXN.PTX_DT_FIN_VERIFIED IS NULL THEN \'OPEN\'\n          WHEN TXN.PTX_DT_FIN_VERIFIED IS NOT NULL\n               AND TXN.PTX_DT_FIN_APPROVED IS NULL THEN \'VERIFIED\'\n          WHEN TXN.PTX_DT_FIN_APPROVED IS NOT NULL\n               AND TXN.PTX_PAYMENT_STATE <> \'PAID\' THEN \'PAYING/APPROVED\'\n          WHEN TXN.PTX_PAYMENT_STATE = \'PAID\' THEN \'PAID\'\n          ELSE TXN.PTX_PAYMENT_STATE\n        END                                                     	AS DISB_STATUS,\n        IFNULL(TXN.PTX_PAYEE_BANK_ACCN, \'-\')                         AS BEN_BANK,\n        IFNULL(TXN.PTX_PAYEE, \'-\')                             AS BEN_ACCN,\n        IFNULL(TXN.PTX_PAYEE, \'-\')                         AS BEN_ACCN_NAME,\n        IFNULL(DATE_FORMAT(TXN.PTX_DT_PAID, \'%Y-%m-%d\'), \'-\')    AS DISB_DT,\n        PAYIN.PTX_PAYMENT_STATE                                  AS CO_PYMNT_STATUS,\n        IFNULL(DATE_FORMAT(PAYIN.PTX_DT_PAID, \'%Y-%m-%d\'), \'-\')  AS CO_PYMNT_DT\n FROM   T_CK_PAYMENT_TXN TXN\n        INNER JOIN T_CK_JOB_TRUCK TRUCK\n                ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', TRUCK.JOB_ID, \'%\')\n        LEFT JOIN (SELECT DN_TO,\n                          DN_FROM,\n                          DN_AMT,\n                          DN_TOTAL,\n                          DN_ID,\n                          DN_JOB_ID,\n                          DN_NO,\n                          DN_DT_ISSUE,\n                          DN_DT_DUE\n                   FROM   T_CK_CT_DEBIT_NOTE) DN_TO\n               ON TRUCK.JOB_ID = DN_TO.DN_JOB_ID\n                  AND TRUCK.JOB_PARTY_CO_FF = DN_TO.DN_TO\n        LEFT JOIN (SELECT INV_NO,\n                          INV_TO,\n                          INV_TOTAL,\n                          INV_DT_ISSUE,\n                          INV_STATE,\n                          INV_ID,\n                          INV_JOB_ID\n                   FROM   T_CK_CT_PLATFORM_INVOICE) INV_CO\n               ON TRUCK.JOB_ID = INV_CO.INV_JOB_ID\n                  AND INV_CO.INV_TO = TRUCK.JOB_PARTY_CO_FF\n        LEFT JOIN (SELECT INV_NO,\n                          INV_TO,\n                          INV_TOTAL,\n                          INV_DT_ISSUE,\n                          INV_STATE,\n                          INV_ID,\n                          INV_JOB_ID\n                   FROM   T_CK_CT_PLATFORM_INVOICE) INV_TO\n               ON TRUCK.JOB_ID = INV_TO.INV_JOB_ID\n                  AND INV_TO.INV_TO = TRUCK.JOB_PARTY_TO\n        LEFT JOIN (SELECT TRUCK.JOB_ID,\n                          TXN.PTX_PAYMENT_STATE,\n                          TXN.PTX_DT_PAID,\n                          TXN.PTX_PAYER,\n                          TXN.PTX_DT_FIN_VERIFIED\n                   FROM   T_CK_PAYMENT_TXN TXN\n                          INNER JOIN T_CK_JOB_TRUCK TRUCK\n                                  ON TXN.PTX_SVC_REF LIKE CONCAT(\'%\', TRUCK.JOB_ID, \'%\')\n                   WHERE  TXN.PTX_TYPE = \'VA\'\n                          AND PTX_STATUS = \'A\') PAYIN\n               ON TRUCK.JOB_ID = PAYIN.JOB_ID\n                  AND TRUCK.JOB_PARTY_CO_FF = PAYIN.PTX_PAYER\n        LEFT JOIN T_CORE_ACCN TO_ACCN\n               ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n        LEFT JOIN T_CORE_ACCN COFF_ACCN\n               ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n WHERE  TXN.PTX_TYPE = \'BNKTF\' \n 		AND TXN.PTX_DT_PAID > \'@FIL_DN_DT_DUE_FROM@\'\n         AND TXN.PTX_DT_PAID < \'@FIL_DN_DT_DUE_TO@\' ');
